/**
 * Typed Drizzle query functions for stats page
 * Replaces raw SQL with type-safe query builders
 */

import { db } from '$lib/server/db';
import { flights, historicalWeather } from '@airways/database/schema';
import {
  sql,
  desc,
  isNotNull,
} from 'drizzle-orm';
import type {
  FilterConfig,
  HeroStats,
  DelayDistribution,
  DayOfWeekStats,
  HourlyStats,
  DailyStats,
  RouteStats,
  FlightNumberStats,
  AircraftStats,
  DelayRecord,
  DailyOtpStats,
  MonthlyStats,
  WeatherBandStats,
  WeatherCodeStats,
  CrosswindStats,
  WorstWeatherDay,
  DelayImpact,
  WorstDelayDay,
  FilterOptions,
} from './types';

