  if (range === 'custom' && dateFrom && dateTo) {
    dateFilter = sql`AND f.flight_date BETWEEN ${dateFrom} AND ${dateTo}`;
  } else if (range === '30') {
    dateFilter = sql`AND f.flight_date >= CURRENT_DATE - INTERVAL '30 days'`;
  } else if (range === '90') {
