    : activeDirection === 'arr'
    ? sql`AND f.arrival_airport = 'GCI'`
    : sql``;

  const dowNum = parseInt(activeDow, 10);
  const monthNum = parseInt(activeMonth, 10);
  const yearNum = parseInt(activeYear, 10);

